func  (this *gemini) ParseMarket(response interface{}) interface{}  {
    //
    // response might be:
    //
    //     btcusd
    //
    // or
    //
    //     [
    //         'BTCUSD',   // symbol
    //         2,          // priceTickDecimalPlaces
    //         8,          // quantityTickDecimalPlaces
    //         '0.00001',  // quantityMinimum
    //         10,         // quantityRoundDecimalPlaces
    //         true        // minimumsAreInclusive
    //     ],
    //
    // or
    //
    //     {
    //         "symbol": "BTCUSD", // perpetuals have 'PERP' suffix, i.e. DOGEUSDPERP
    //         "base_currency": "BTC",
    //         "quote_currency": "USD",
    //         "tick_size": 1E-8,
    //         "quote_increment": 0.01,
    //         "min_order_size": "0.00001",
    //         "status": "open",
    //         "wrap_enabled": false
    //         "product_type": "swap", // only in perps
    //         "contract_type": "linear", // only in perps
    //         "contract_price_currency": "GUSD" // only in perps
    //     }
    //
    var marketId interface{} = nil
    var baseId interface{} = nil
    var quoteId interface{} = nil
    var settleId interface{} = nil
    var tickSize interface{} = nil
    var amountPrecision interface{} = nil
    var minSize interface{} = nil
    var status interface{} = nil
    var swap interface{} = false
    var contractSize interface{} = nil
    var linear interface{} = nil
    var inverse interface{} = nil
    var isString interface{} =     (ccxt.IsString(response))
    var isArray interface{} =     (ccxt.IsArray(response))
    if ccxt.IsTrue(!ccxt.IsTrue(isString) && !ccxt.IsTrue(isArray)) {
        marketId = this.SafeStringLower(response, "symbol")
        amountPrecision = this.SafeNumber(response, "tick_size") // right, exchange has an imperfect naming and this turns out to be an amount-precision
        tickSize = this.SafeNumber(response, "quote_increment") // this is tick-size actually
        minSize = this.SafeNumber(response, "min_order_size")
        status = this.ParseMarketActive(this.SafeString(response, "status"))
        baseId = this.SafeString(response, "base_currency")
        quoteId = this.SafeString(response, "quote_currency")
        settleId = this.SafeString(response, "contract_price_currency")
    } else {
        // if no detailed API was called, then parse either string or array
        if ccxt.IsTrue(isString) {
            marketId = response
        } else {
            marketId = this.SafeStringLower(response, 0)
            tickSize = this.ParseNumber(this.ParsePrecision(this.SafeString(response, 1))) // priceTickDecimalPlaces
            amountPrecision = this.ParseNumber(this.ParsePrecision(this.SafeString(response, 2))) // quantityTickDecimalPlaces
            minSize = this.SafeNumber(response, 3) // quantityMinimum
        }
        var marketIdUpper interface{} = ccxt.ToUpper(marketId)
        var isPerp interface{} =         (ccxt.IsGreaterThanOrEqual(ccxt.GetIndexOf(marketIdUpper, "PERP"), 0))
        var marketIdWithoutPerp interface{} = ccxt.Replace(marketIdUpper, "PERP", "")
        var conflictingMarkets interface{} = this.SafeDict(this.Options, "conflictingMarkets", map[string]interface{} {})
        var lowerCaseId interface{} = ccxt.ToLower(marketIdWithoutPerp)
        if ccxt.IsTrue(ccxt.InOp(conflictingMarkets, lowerCaseId)) {
            var conflictingMarket interface{} = ccxt.GetValue(conflictingMarkets, lowerCaseId)
            baseId = ccxt.GetValue(conflictingMarket, "base")
            quoteId = ccxt.GetValue(conflictingMarket, "quote")
            if ccxt.IsTrue(isPerp) {
                settleId = ccxt.GetValue(conflictingMarket, "quote")
            }
        } else {
            var quoteCurrencies interface{} = this.HandleOption("fetchMarketsFromAPI", "quoteCurrencies", []interface{}{})
            for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(quoteCurrencies)); i++ {
                var quoteCurrency interface{} = ccxt.GetValue(quoteCurrencies, i)
                if ccxt.IsTrue(ccxt.EndsWith(marketIdWithoutPerp, quoteCurrency)) {
                    var quoteLength interface{} = this.ParseToInt(ccxt.Multiply(ccxt.OpNeg(1), ccxt.GetArrayLength(quoteCurrency)))
                    baseId = ccxt.Slice(marketIdWithoutPerp, 0, quoteLength)
                    quoteId = quoteCurrency
                    if ccxt.IsTrue(isPerp) {
                        settleId = quoteCurrency // always same
                    }
                    break
                }
            }
        }
    }
    var base interface{} = this.SafeCurrencyCode(baseId)
    var quote interface{} = this.SafeCurrencyCode(quoteId)
    var settle interface{} = this.SafeCurrencyCode(settleId)
    var symbol interface{} = ccxt.Add(ccxt.Add(base, "/"), quote)
    if ccxt.IsTrue(!ccxt.IsEqual(settleId, nil)) {
        symbol = ccxt.Add(ccxt.Add(symbol, ":"), settle)
        swap = true
        contractSize = tickSize // always same
        linear = true // always linear
        inverse = false
    }
    var typeVar interface{} = ccxt.Ternary(ccxt.IsTrue(swap), "swap", "spot")
    return map[string]interface{} {
        "id": marketId,
        "symbol": symbol,
        "base": base,
        "quote": quote,
        "settle": settle,
        "baseId": baseId,
        "quoteId": quoteId,
        "settleId": settleId,
        "type": typeVar,
        "spot": !ccxt.IsTrue(swap),
        "margin": false,
        "swap": swap,
        "future": false,
        "option": false,
        "active": status,
        "contract": swap,
        "linear": linear,
        "inverse": inverse,
        "contractSize": contractSize,
        "expiry": nil,
        "expiryDatetime": nil,
        "strike": nil,
        "optionType": nil,
        "precision": map[string]interface{} {
            "price": tickSize,
            "amount": amountPrecision,
        },
        "limits": map[string]interface{} {
            "leverage": map[string]interface{} {
                "min": nil,
                "max": nil,
            },
            "amount": map[string]interface{} {
                "min": minSize,
                "max": nil,
            },
            "price": map[string]interface{} {
                "min": nil,
                "max": nil,
            },
            "cost": map[string]interface{} {
                "min": nil,
                "max": nil,
            },
        },
        "created": nil,
        "info": response,
    }
}
